/* ============================================================
   KAIPI IMPULSA — TOKENS DE MARCA
   Cambia estas 4 variables y toda la página se reviste sola.
   ============================================================ */
:root{
  /* --- identidad Kaipi Impulsa --- */
  --accent:#C9DC4F;
  --accent-soft:rgba(201,220,79,.14);
  --accent-line:rgba(201,220,79,.38);
  --accent-text:#C9DC4F;
  --on-accent:#1A1A12;

  --paper:#1E1D1B;        /* fondo base */
  --paper-2:#262421;      /* superficies y secciones tintadas */
  --chip:#2C2A26;         /* módulos dentro de diagramas */
  --ink:#EDEAE0;          /* texto principal (crema) */
  --ink-2:#CBC7BA;
  --muted:#948F84;
  --line:#34322D;
  --line-2:#45423B;

  /* bloque invertido de alto contraste (crema) */
  --dark:#F1EEE4;
  --dark-2:#FAF8F1;
  --dark-line:#DDD8C7;
  --dark-muted:#6B675C;

  --display:'Anton','Arial Narrow',sans-serif;
  --body:'Inter',system-ui,-apple-system,sans-serif;
  --mono:'Inter',system-ui,sans-serif;

  --max:1200px;
  --r:14px;
  --r-lg:22px;
  --pad:clamp(64px,7vw,116px);
}

*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:88px;-webkit-text-size-adjust:100%}
body{
  margin:0;background:var(--paper);color:var(--ink);
  font-family:var(--body);font-size:17px;line-height:1.6;
  -webkit-font-smoothing:antialiased;overflow-x:hidden;
}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}
::selection{background:var(--accent);color:var(--on-accent)}
:focus-visible{outline:2.5px solid var(--accent);outline-offset:3px;border-radius:4px}

/* ---------- layout ---------- */
.wrap{width:min(calc(100% - 40px),var(--max));margin-inline:auto}
.sec{padding-block:var(--pad);position:relative}
.sec--tint{background:var(--paper-2)}
.sec--dark{background:var(--dark);color:#fff}
.sec--dark .lead,.sec--dark .muted{color:var(--dark-muted)}
.hr{height:1px;background:var(--line);border:0;margin:0}

/* ---------- tipografía ---------- */
h1,h2,h3,h4,p{margin:0}
.display{font-family:var(--display);font-weight:700;letter-spacing:-.03em;line-height:1.02}
h1{font-family:var(--display);font-weight:700;letter-spacing:-.035em;line-height:1.0;
   font-size:clamp(40px,5.6vw,74px)}
h2{font-family:var(--display);font-weight:700;letter-spacing:-.03em;line-height:1.05;
   font-size:clamp(31px,3.9vw,52px);max-width:19ch}
h2.wide{max-width:26ch}
h3{font-family:var(--display);font-weight:600;letter-spacing:-.015em;font-size:20px;line-height:1.2}
.lead{font-size:clamp(17px,1.35vw,20px);color:var(--muted);max-width:62ch;line-height:1.55}
.muted{color:var(--muted)}
.small{font-size:14.5px;line-height:1.55}
.eyebrow{
  display:inline-flex;align-items:center;gap:9px;
  font-family:var(--mono);font-size:12px;font-weight:500;
  letter-spacing:.16em;text-transform:uppercase;color:var(--accent);
  margin-bottom:20px;
}
.eyebrow::before{content:"";width:22px;height:1px;background:var(--accent)}
.sec--dark .eyebrow{color:var(--accent)}
.num{font-family:var(--mono);font-size:12px;letter-spacing:.1em;color:var(--muted)}
.sec-head{max-width:900px;margin-bottom:clamp(40px,4.5vw,64px)}
.sec-head .lead{margin-top:20px}

/* ---------- botones ---------- */
.btn{
  display:inline-flex;align-items:center;justify-content:center;gap:10px;
  min-height:54px;padding:0 26px;border-radius:100px;
  font-weight:600;font-size:16px;letter-spacing:-.01em;
  background:var(--accent);color:var(--on-accent);
  border:1.5px solid var(--accent);
  transition:transform .18s ease,box-shadow .18s ease,background .18s ease;
  box-shadow:0 1px 0 rgba(0,0,0,.04);
}
.btn:hover{transform:translateY(-2px);box-shadow:0 10px 24px -10px var(--accent)}
.btn:active{transform:translateY(0)}
.btn--ghost{background:transparent;color:var(--ink);border-color:var(--line-2)}
.btn--ghost:hover{border-color:var(--ink);box-shadow:none}
.sec--dark .btn--ghost{color:#fff;border-color:#454039}
.sec--dark .btn--ghost:hover{border-color:#fff}
.btn--sm{min-height:46px;padding:0 20px;font-size:15px}
.btn .arw{transition:transform .18s ease}
.btn:hover .arw{transform:translateX(3px)}

/* ---------- header ---------- */
.hdr{
  position:sticky;top:0;z-index:60;
  background:rgba(255,255,255,.82);backdrop-filter:blur(14px) saturate(1.6);
  border-bottom:1px solid transparent;transition:border-color .25s ease,box-shadow .25s ease;
}
.hdr.is-stuck{border-bottom-color:var(--line);box-shadow:0 8px 24px -22px rgba(0,0,0,.5)}
.hdr__in{min-height:76px;display:flex;align-items:center;justify-content:space-between;gap:24px}
.brand{display:flex;align-items:center;gap:11px}
.brand__mark{
  width:34px;height:34px;border-radius:9px;background:var(--ink);
  display:grid;place-items:center;flex:none;position:relative;overflow:hidden;
}
.brand__mark svg{width:19px;height:19px}
.brand__txt{display:flex;flex-direction:column;line-height:1.05}
.brand__name{font-family:var(--display);font-weight:800;font-size:16.5px;letter-spacing:-.02em}
.brand__sub{font-family:var(--mono);font-size:9.5px;letter-spacing:.13em;text-transform:uppercase;color:var(--muted)}
.hdr__cta{display:flex;align-items:center;gap:12px}

/* ---------- hero ---------- */
.hero{padding-top:clamp(52px,5vw,84px);padding-bottom:clamp(56px,5vw,90px);position:relative;overflow:hidden}
.hero::after{
  content:"";position:absolute;inset:auto -10% -60% 40%;height:70%;
  background:radial-gradient(closest-side,var(--accent-soft),transparent 70%);pointer-events:none;
}
.hero__grid{display:grid;grid-template-columns:1.02fr .98fr;gap:clamp(36px,4vw,64px);align-items:center;position:relative;z-index:1}
.hero h1{margin-bottom:26px}
.hero h1 em{font-style:normal;position:relative;white-space:nowrap}
.hero h1 em::after{
  content:"";position:absolute;left:-.04em;right:-.04em;bottom:.08em;height:.36em;
  background:var(--accent-soft);border-bottom:2.5px solid var(--accent);z-index:-1;
}
.hero .lead{font-size:clamp(17px,1.45vw,20.5px);max-width:52ch}
.hero__cta{display:flex;flex-wrap:wrap;gap:14px;margin-top:34px}
.hero__note{display:flex;align-items:center;gap:10px;margin-top:22px;font-size:14px;color:var(--muted)}
.dot{width:7px;height:7px;border-radius:50%;background:var(--accent);flex:none;position:relative}
.dot::after{content:"";position:absolute;inset:-4px;border-radius:50%;border:1px solid var(--accent-line);animation:pulse 2.4s ease-out infinite}
@keyframes pulse{0%{transform:scale(.6);opacity:1}100%{transform:scale(1.5);opacity:0}}
.hero__visual{position:relative}

/* tarjeta de diagrama reutilizable */
.figure{
  background:var(--paper);border:1px solid var(--line);border-radius:var(--r-lg);
  padding:clamp(20px,2.2vw,30px);box-shadow:0 30px 60px -46px rgba(20,16,12,.55);
}
.figure--flat{box-shadow:none}
.figure__cap{
  display:flex;align-items:center;justify-content:space-between;gap:12px;
  font-family:var(--mono);font-size:11px;letter-spacing:.13em;text-transform:uppercase;
  color:var(--muted);margin-bottom:18px;padding-bottom:14px;border-bottom:1px solid var(--line);
}
.sec--dark .figure{background:var(--dark-2);border-color:var(--dark-line);box-shadow:none}
.sec--dark .figure__cap{color:var(--dark-muted);border-bottom-color:var(--dark-line)}
.svg-fig{width:100%;height:auto;display:block}

/* ---------- logos / confianza ---------- */
.trust{display:grid;grid-template-columns:minmax(200px,260px) 1fr;gap:clamp(28px,4vw,60px);align-items:center}
.logos{display:grid;grid-template-columns:repeat(6,1fr);gap:14px}
.logo-slot{
  height:76px;border:1px dashed var(--line-2);border-radius:12px;display:grid;place-items:center;
  font-family:var(--mono);font-size:10.5px;letter-spacing:.12em;color:#A6A29A;background:var(--paper);
  transition:border-color .2s,color .2s;
}
.logo-slot:hover{border-color:var(--accent);color:var(--accent)}
.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;margin-top:26px}
.stat{background:var(--paper-2);padding:22px 24px}
.stat b{display:block;font-family:var(--display);font-size:clamp(28px,3vw,40px);letter-spacing:-.03em;line-height:1}
.stat span{font-family:var(--mono);font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}

/* ---------- grid de problemas ---------- */
.prob-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);border:1px solid var(--line);border-radius:var(--r-lg);overflow:hidden}
.prob{background:var(--paper);padding:clamp(24px,2.4vw,34px);transition:background .2s}
.prob:hover{background:var(--paper-2)}
.prob__i{width:38px;height:38px;border-radius:10px;background:var(--accent-soft);display:grid;place-items:center;margin-bottom:20px}
.prob__i svg{width:19px;height:19px;stroke:var(--accent);fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.prob h3{margin-bottom:9px}
.prob p{font-size:15.5px;color:var(--muted);line-height:1.55}

/* ---------- dos columnas genérico ---------- */
.two{display:grid;grid-template-columns:1fr 1fr;gap:clamp(36px,4.5vw,72px);align-items:center}
.two--start{align-items:start}
.leak-list{list-style:none;margin:26px 0 0;padding:0;display:grid;gap:0}
.leak-list li{display:flex;gap:14px;align-items:flex-start;padding:13px 0;border-top:1px solid var(--line);font-size:15.5px}
.leak-list li:last-child{border-bottom:1px solid var(--line)}
.leak-list svg{width:15px;height:15px;flex:none;margin-top:4px;stroke:var(--accent);stroke-width:2;fill:none;stroke-linecap:round}
.pull{
  margin-top:34px;padding:26px 28px;border-radius:var(--r);
  background:var(--ink);color:#fff;font-family:var(--display);font-weight:600;
  font-size:clamp(19px,1.7vw,23px);letter-spacing:-.02em;line-height:1.28;
}
.pull b{color:var(--accent);font-weight:600}

/* ---------- comparativa ---------- */
.cmp{display:grid;grid-template-columns:1fr 76px 1fr;gap:0;align-items:stretch}
.cmp__col{border:1px solid var(--line);border-radius:var(--r-lg);padding:clamp(22px,2.4vw,32px);background:var(--paper)}
.cmp__col--now{background:var(--paper-2);border-style:dashed}
.cmp__col--new{border-color:var(--ink);box-shadow:0 30px 60px -50px rgba(20,16,12,.7);position:relative;overflow:hidden}
.cmp__col--new::before{content:"";position:absolute;top:0;left:0;right:0;height:4px;background:var(--accent)}
.cmp__title{display:flex;align-items:center;gap:11px;margin-bottom:22px;font-family:var(--display);font-weight:700;font-size:19px;letter-spacing:-.02em}
.cmp__tag{font-family:var(--mono);font-size:10px;letter-spacing:.12em;text-transform:uppercase;padding:5px 9px;border-radius:6px;background:var(--paper);border:1px solid var(--line-2);color:var(--muted)}
.cmp__col--new .cmp__tag{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}
.cmp__list{list-style:none;margin:0;padding:0;display:grid;gap:10px}
.cmp__list li{font-size:15.5px;padding:13px 15px;border-radius:10px;display:flex;align-items:center;gap:12px}
.cmp__col--now li{background:var(--paper);border:1px dashed var(--line-2);color:var(--muted)}
.cmp__col--new li{background:var(--paper-2);border:1px solid transparent;position:relative}
.cmp__col--new li::before{content:"";position:absolute;left:-1px;top:14px;bottom:14px;width:2px;background:var(--accent);border-radius:2px}
.cmp__mid{display:grid;place-items:center}
.cmp__arrow{width:52px;height:52px;border-radius:50%;background:var(--ink);display:grid;place-items:center}
.cmp__arrow svg{width:20px;height:20px;stroke:var(--accent);stroke-width:2;fill:none}

/* ---------- tabs ---------- */
.tabs{display:grid;grid-template-columns:300px 1fr;gap:clamp(24px,2.6vw,44px);align-items:start}
.tabs__nav{display:flex;flex-direction:column;gap:4px;position:sticky;top:104px}
.tab-btn{
  display:flex;align-items:center;gap:14px;text-align:left;padding:16px 18px;border-radius:12px;
  border:1px solid transparent;font-weight:600;font-size:16px;color:var(--muted);
  transition:background .2s,color .2s,border-color .2s;
}
.tab-btn i{font-family:var(--mono);font-style:normal;font-size:12px;letter-spacing:.08em;opacity:.65}
.tab-btn:hover{background:var(--paper-2);color:var(--ink)}
.tab-btn.is-active{background:var(--paper);border-color:var(--line);color:var(--ink);box-shadow:0 14px 30px -26px rgba(20,16,12,.7)}
.tab-btn.is-active i{color:var(--accent);opacity:1}
.sec--tint .tab-btn:hover{background:#e9e7e2}
.sec--tint .tab-btn.is-active{background:var(--paper)}
.panel{display:none;background:var(--paper);border:1px solid var(--line);border-radius:var(--r-lg);padding:clamp(26px,3vw,44px)}
.panel.is-active{display:block;animation:fadeUp .35s ease}
@keyframes fadeUp{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.panel__label{font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--accent);margin-bottom:14px;display:block}
.panel h3{font-size:clamp(22px,2.2vw,30px);line-height:1.15;max-width:22ch;margin-bottom:10px;font-weight:700}
.panel__do{margin-top:30px;padding-top:26px;border-top:1px solid var(--line)}
.panel__do h4{font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);font-weight:500;margin-bottom:16px}
.chips{display:flex;flex-wrap:wrap;gap:9px;list-style:none;margin:0;padding:0}
.chips li{font-size:14.5px;padding:9px 14px;border-radius:100px;background:var(--paper-2);border:1px solid var(--line)}
.panel__slot{margin-top:26px;border:1px dashed var(--line-2);border-radius:var(--r);padding:20px;display:flex;align-items:center;gap:14px;font-family:var(--mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:#A6A29A}
.panel__slot svg{width:20px;height:20px;stroke:#A6A29A;fill:none;stroke-width:1.6}

/* ---------- sistema (dark) ---------- */
.sys{display:grid;grid-template-columns:1.15fr .85fr;gap:clamp(30px,3.5vw,60px);align-items:center}
.sys__svg{max-width:660px;margin-inline:auto}
.node{cursor:pointer}
.node rect{fill:var(--dark-2);stroke:var(--dark-line);stroke-width:1.5;transition:fill .2s,stroke .2s}
.node text{font-family:var(--body);font-size:15px;font-weight:600;fill:#fff}
.node .node__n{font-family:var(--mono);font-size:11px;letter-spacing:.1em;fill:var(--dark-muted)}
.node:hover rect,.node.is-on rect{fill:#26221E;stroke:var(--accent)}
.node.is-on .node__n{fill:var(--accent)}
.ring{fill:none;stroke:var(--dark-line);stroke-width:1.5}
.ring-flow{fill:none;stroke:var(--accent);stroke-width:2;stroke-dasharray:26 1290;stroke-linecap:round;animation:flow 6s linear infinite}
@keyframes flow{to{stroke-dashoffset:-1316}}
.feedback{fill:none;stroke:var(--accent);stroke-width:1.5;stroke-dasharray:5 6;opacity:.75}
.sys-detail{border-left:2px solid var(--accent);padding-left:24px;min-height:190px}
.sys-detail__n{font-family:var(--mono);font-size:12px;letter-spacing:.14em;color:var(--accent);text-transform:uppercase}
.sys-detail h3{font-size:clamp(24px,2.4vw,34px);margin:12px 0 14px;font-weight:700}
.sys-detail p{color:var(--dark-muted);font-size:16.5px;max-width:44ch}
.sys-detail__meta{margin-top:22px;font-family:var(--mono);font-size:11.5px;letter-spacing:.1em;text-transform:uppercase;color:#7C766E}
.sys-mobile{display:none}
.sys-step{display:grid;grid-template-columns:44px 1fr;gap:16px;padding-bottom:22px;position:relative}
.sys-step::before{content:"";position:absolute;left:21px;top:44px;bottom:0;width:1.5px;background:var(--dark-line)}
.sys-step:last-child::before{background:linear-gradient(var(--accent),transparent)}
.sys-step__n{width:44px;height:44px;border-radius:12px;border:1.5px solid var(--dark-line);display:grid;place-items:center;font-family:var(--mono);font-size:13px;background:var(--dark-2);position:relative;z-index:1}
.sys-step h4{font-size:17px;font-family:var(--display);font-weight:600;margin:9px 0 4px}
.sys-step p{font-size:15px;color:var(--dark-muted);margin-bottom:4px}
.sys-loop{margin-top:6px;padding:16px 18px;border:1.5px dashed var(--accent);border-radius:12px;font-size:14.5px;color:#fff}

/* ---------- timeline ---------- */
.tl{border-top:1px solid var(--line)}
.tl__item{border-bottom:1px solid var(--line)}
.tl__head{width:100%;display:grid;grid-template-columns:74px 1fr auto;gap:20px;align-items:center;padding:26px 0;text-align:left}
.tl__n{font-family:var(--mono);font-size:13px;color:var(--accent);letter-spacing:.08em}
.tl__t{font-family:var(--display);font-weight:600;font-size:clamp(19px,1.9vw,25px);letter-spacing:-.02em}
.tl__plus{width:38px;height:38px;border-radius:50%;border:1px solid var(--line-2);display:grid;place-items:center;flex:none;transition:background .2s,border-color .2s,transform .25s}
.tl__plus svg{width:14px;height:14px;stroke:var(--ink);stroke-width:2;fill:none;transition:stroke .2s}
.tl__item.is-open .tl__plus{background:var(--accent);border-color:var(--accent);transform:rotate(45deg)}
.tl__item.is-open .tl__plus svg{stroke:var(--on-accent)}
.tl__body{display:grid;grid-template-rows:0fr;transition:grid-template-rows .34s ease}
.tl__item.is-open .tl__body{grid-template-rows:1fr}
.tl__inner{overflow:hidden}
.tl__content{display:grid;grid-template-columns:74px 1fr 340px;gap:20px;padding-bottom:30px}
.tl__content p{grid-column:2;color:var(--muted);max-width:56ch}
.tl__deliver{grid-column:3;background:var(--paper-2);border:1px solid var(--line);border-radius:var(--r);padding:18px 20px}
.tl__deliver span{font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--accent);display:block;margin-bottom:8px}
.tl__deliver p{grid-column:auto;font-size:15px;color:var(--ink-2);max-width:none}

/* ---------- métricas ---------- */
.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:1px;background:var(--line);border:1px solid var(--line);border-radius:var(--r-lg);overflow:hidden}
.metric{background:var(--paper);padding:28px 24px 30px;transition:background .2s}
.metric:hover{background:var(--paper-2)}
.metric b{font-family:var(--mono);font-size:12px;color:var(--accent);letter-spacing:.1em;display:block;margin-bottom:26px}
.metric h3{font-size:18px;margin-bottom:8px}
.metric p{font-size:14.5px;color:var(--muted);line-height:1.5}
.funnel{margin-top:26px;display:grid;gap:10px}
.funnel__row{display:grid;grid-template-columns:150px 1fr;align-items:center;gap:18px}
.funnel__row span{font-family:var(--mono);font-size:11.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
.funnel__bar{height:44px;border-radius:8px;background:var(--paper-2);border:1px solid var(--line);position:relative;overflow:hidden}
.funnel__fill{position:absolute;inset:0 auto 0 0;background:var(--ink);border-radius:7px;transform-origin:left;transform:scaleX(0);transition:transform 1.1s cubic-bezier(.2,.7,.2,1)}
.is-in .funnel__fill{transform:scaleX(1)}
.funnel__row:last-child .funnel__fill{background:var(--accent)}
.funnel__note{margin-top:16px;font-size:13.5px;color:var(--muted);display:flex;gap:9px;align-items:center}

/* ---------- casos ---------- */
.cases{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.case{
  position:relative;border:1px solid var(--line);border-radius:var(--r-lg);background:var(--paper-2);
  overflow:hidden;display:flex;flex-direction:column;
  transition:transform .28s cubic-bezier(.2,.7,.2,1),border-color .28s,box-shadow .28s;
}
.case--live:hover{transform:translateY(-4px);border-color:var(--line-2);box-shadow:0 30px 60px -44px rgba(0,0,0,.9)}

/* --- media --- */
.case__media{
  position:relative;aspect-ratio:4/3;overflow:hidden;background:#1c1a18;
  display:grid;place-items:center;
}
.case__media::before{
  content:"";position:absolute;inset:0;
  background:
    radial-gradient(120% 90% at 50% 0%,rgba(201,220,79,.07),transparent 62%),
    repeating-linear-gradient(135deg,transparent 0 26px,rgba(255,255,255,.016) 26px 27px);
}
.case__media img.case__shot{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.case__media .case__shot--hotel{object-position:center center}
.case__logo{
  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:2;
  max-width:min(76%,330px);max-height:138px;
  width:auto;height:auto;object-fit:contain;opacity:.99;
  filter:drop-shadow(0 2px 4px rgba(0,0,0,.95)) drop-shadow(0 10px 22px rgba(0,0,0,.75)) drop-shadow(0 20px 40px rgba(0,0,0,.45));
  transition:transform .35s cubic-bezier(.2,.7,.2,1);
}
.case--live:hover .case__logo{transform:translate(-50%,-50%) scale(1.04)}
.case__logo--hotel{max-width:min(90%,420px);max-height:190px}
.case__media .case__shot--vidam{object-position:center center}
.case__logo--vidam{max-width:min(68%,300px);max-height:125px;filter:drop-shadow(0 3px 6px rgba(0,0,0,.98)) drop-shadow(0 12px 28px rgba(0,0,0,.85)) drop-shadow(0 24px 48px rgba(0,0,0,.58))}
.case__media .case__shot--caban{object-position:center center}
.case__logo--caban{max-width:min(82%,360px);max-height:220px}
.case__tag{
  position:absolute;z-index:3;left:16px;top:16px;
  font-family:var(--mono);font-size:9.5px;font-weight:600;letter-spacing:.16em;text-transform:uppercase;
  padding:6px 10px;border-radius:100px;color:var(--ink);
  background:rgba(18,17,15,.55);backdrop-filter:blur(8px);border:1px solid rgba(255,255,255,.09);
}

/* --- body --- */
.case__body{padding:24px 24px 26px;display:flex;flex-direction:column;gap:11px;flex:1}
.case__eyebrow{
  font-family:var(--mono);font-size:10px;font-weight:600;letter-spacing:.15em;
  text-transform:uppercase;color:var(--accent);
}
.case h3{font-size:22px;line-height:1.12;margin:0;letter-spacing:-.02em}
.case__summary{font-size:14.5px;line-height:1.55;color:var(--muted);margin:0}

/* --- resultado: cifra grande, sin bloque macizo --- */
.case__result{
  margin-top:auto;padding-top:18px;border-top:1px solid var(--line);
  display:flex;align-items:flex-end;gap:12px;
}
.case__result strong{
  font-family:var(--display);font-weight:400;letter-spacing:.01em;
  font-size:46px;line-height:.82;color:var(--accent);
  font-variant-numeric:tabular-nums;
}
.case__result span{
  font-size:12.5px;line-height:1.35;color:var(--ink-2);
  max-width:14ch;padding-bottom:3px;
}

/* --- tarjeta placeholder mientras esperamos arte final --- */
.case--placeholder .case__media{
  background:
    radial-gradient(120% 90% at 50% 0%,rgba(201,220,79,.07),transparent 62%),
    linear-gradient(180deg,#161513 0%,#1b1917 100%);
}
.case--placeholder .case__media::before{
  background:repeating-linear-gradient(135deg,transparent 0 26px,rgba(255,255,255,.015) 26px 27px);
}
.case__placeholderMark{
  position:relative;z-index:2;display:grid;place-items:center;gap:12px;text-align:center;
  padding:28px;color:#8d877f;
}
.case__placeholderMark svg{width:28px;height:28px;stroke:#8d877f;fill:none;stroke-width:1.5}
.case__placeholderMark em{
  font-style:normal;font-family:var(--mono);font-size:10px;font-weight:600;
  letter-spacing:.17em;text-transform:uppercase;color:#8d877f;
}
.case__placeholderMark span{
  font-family:var(--display);font-size:28px;line-height:.95;letter-spacing:-.02em;color:#b8b1a8;
}

.cases__note{
  margin-top:22px;display:flex;gap:10px;align-items:flex-start;
  font-size:13px;line-height:1.55;color:var(--muted);
}
.cases__note .dot{margin-top:7px}
@media (max-width:760px){.case__media{aspect-ratio:16/10}}


/* ---------- encaje ---------- */
.fit{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.fit__col{border-radius:var(--r-lg);padding:clamp(26px,2.8vw,38px);border:1px solid var(--line)}
.fit__col--yes{background:var(--ink);color:#fff;border-color:var(--ink)}
.fit__col--no{background:var(--paper);}
.fit__col h3{font-size:clamp(21px,2vw,27px);margin-bottom:24px;display:flex;align-items:center;gap:12px;font-weight:700}
.fit__col ul{list-style:none;margin:0;padding:0;display:grid;gap:2px}
.fit__col li{display:flex;gap:14px;align-items:flex-start;padding:14px 0;font-size:16px;border-top:1px solid var(--line)}
.fit__col--yes li{border-top-color:#2C2824}
.fit__col li svg{width:17px;height:17px;flex:none;margin-top:4px;stroke-width:2;fill:none;stroke-linecap:round}
.fit__col--yes li svg{stroke:var(--accent)}
.fit__col--no li{color:var(--muted)}
.fit__col--no li svg{stroke:var(--line-2)}
.fit__cta{margin-top:36px;display:flex;flex-wrap:wrap;align-items:center;gap:18px}

/* ---------- equipo ---------- */
.team{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(30px,3.5vw,56px);align-items:center}
.team__media{aspect-ratio:4/3;border-radius:var(--r-lg);border:1px dashed var(--line-2);background:var(--paper-2);display:grid;place-items:center;gap:12px;text-align:center;padding:24px}
.team__media svg{width:34px;height:34px;stroke:#A6A29A;fill:none;stroke-width:1.4}
.team__media span{font-family:var(--mono);font-size:11px;letter-spacing:.13em;text-transform:uppercase;color:#A6A29A}
.skills{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;margin-top:30px}
.skill{background:var(--paper);padding:16px 18px;display:flex;align-items:center;gap:11px;font-size:15px;font-weight:500}
.skill i{width:6px;height:6px;border-radius:50%;background:var(--accent);flex:none}
.sec--tint .skill{background:var(--paper)}

/* ---------- testimonios ---------- */
.quotes{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.quote{background:var(--paper);border:1px solid var(--line);border-radius:var(--r-lg);padding:30px 28px;display:flex;flex-direction:column;gap:22px}
.quote__mark{font-family:var(--display);font-size:44px;line-height:.6;color:var(--accent)}
.quote p{font-size:17px;line-height:1.5;color:var(--ink)}
.quote footer{margin-top:auto;display:flex;align-items:center;gap:12px;padding-top:18px;border-top:1px solid var(--line)}
.quote__av{width:38px;height:38px;border-radius:50%;background:var(--paper-2);border:1px dashed var(--line-2);flex:none}
.quote__who b{display:block;font-size:14.5px}
.quote__who span{font-family:var(--mono);font-size:11px;letter-spacing:.08em;color:var(--muted)}

/* FAQ: titular forzado a 2 líneas en escritorio */
.faq-title{max-width:none!important}
.faq-title span{display:block;white-space:nowrap}
@media (max-width:760px){.faq-title span{white-space:normal}}

/* ---------- faq ---------- */
.faq{max-width:900px;margin-inline:auto;border-top:1px solid var(--line)}
.faq__item{border-bottom:1px solid var(--line)}
.faq__q{width:100%;display:flex;align-items:center;justify-content:space-between;gap:24px;padding:24px 0;text-align:left;
  font-family:var(--display);font-weight:600;font-size:clamp(17px,1.5vw,20px);letter-spacing:-.015em}
.faq__q:hover{color:var(--accent)}
.faq__ic{width:30px;height:30px;flex:none;border-radius:50%;border:1px solid var(--line-2);display:grid;place-items:center;transition:transform .3s,background .2s,border-color .2s}
.faq__ic svg{width:12px;height:12px;stroke:var(--ink);stroke-width:2.2;fill:none;transition:stroke .2s}
.faq__item.is-open .faq__ic{background:var(--accent);border-color:var(--accent);transform:rotate(45deg)}
.faq__item.is-open .faq__ic svg{stroke:var(--on-accent)}
.faq__a{display:grid;grid-template-rows:0fr;transition:grid-template-rows .32s ease}
.faq__item.is-open .faq__a{grid-template-rows:1fr}
.faq__a>div{overflow:hidden}
.faq__a p{padding-bottom:26px;color:var(--muted);max-width:70ch;font-size:16px}

/* ---------- cta final ---------- */
.cta-final{position:relative;overflow:hidden}
.cta-final::before{content:"";position:absolute;top:-30%;right:-10%;width:60%;height:160%;
  background:radial-gradient(closest-side,rgba(255,74,28,.18),transparent 70%);pointer-events:none}
.cta-final__grid{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(34px,4vw,64px);align-items:center;position:relative;z-index:1}
.cta-final h2{font-size:clamp(34px,4.4vw,60px)}
.cta-final .btn{margin-top:34px}
.micro{margin-top:18px;font-size:13.5px;color:var(--dark-muted);display:flex;align-items:center;gap:9px}
.micro svg{width:15px;height:15px;stroke:var(--accent);fill:none;stroke-width:1.8}

/* ---------- footer ---------- */
.ftr{background:var(--dark);color:#fff;padding-top:64px;padding-bottom:34px;border-top:1px solid var(--dark-line)}
.ftr__grid{display:grid;grid-template-columns:1.4fr repeat(3,1fr);gap:36px}
.ftr h4{font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--dark-muted);font-weight:500;margin-bottom:18px}
.ftr ul{list-style:none;margin:0;padding:0;display:grid;gap:11px;font-size:15px}
.ftr ul a{color:#D9D5CF}
.ftr ul a:hover{color:var(--accent)}
.ftr__brand p{color:var(--dark-muted);font-size:15px;max-width:34ch;margin-top:16px}
.ftr__bot{margin-top:52px;padding-top:22px;border-top:1px solid var(--dark-line);display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;
  font-family:var(--mono);font-size:11.5px;letter-spacing:.1em;text-transform:uppercase;color:#7C766E}
.ftr .brand__mark{background:var(--accent)}
.ftr .brand__sub{color:var(--dark-muted)}

/* ---------- barra móvil + panel de marca ---------- */
.mbar{position:fixed;left:0;right:0;bottom:0;z-index:55;display:none;transform:translateY(115%);
  transition:transform .3s cubic-bezier(.2,.7,.2,1);padding:12px 16px calc(12px + env(safe-area-inset-bottom));
  background:rgba(255,255,255,.92);backdrop-filter:blur(12px);border-top:1px solid var(--line)}
.mbar.is-on{transform:none}
.mbar .btn{width:100%}
/* ---------- reveal ---------- */
.rv{opacity:0;transform:translateY(18px);transition:opacity .6s ease,transform .6s cubic-bezier(.2,.7,.2,1)}
.rv.is-in{opacity:1;transform:none}

/* ---------- responsive ---------- */
@media (max-width:1080px){
  .hero__grid,.two,.sys,.team,.cta-final__grid{grid-template-columns:1fr}
  .sys__svg{max-width:560px}
  .tabs{grid-template-columns:1fr}
  .tabs__nav{position:static;flex-direction:row;overflow-x:auto;gap:8px;padding-bottom:6px;scrollbar-width:none}
  .tabs__nav::-webkit-scrollbar{display:none}
  .tab-btn{white-space:nowrap;border:1px solid var(--line);background:var(--paper)}
  .metrics{grid-template-columns:repeat(2,1fr)}
  .cases,.quotes,.prob-grid{grid-template-columns:repeat(2,1fr)}
  .tl__content{grid-template-columns:74px 1fr}
  .tl__deliver{grid-column:2}
  .ftr__grid{grid-template-columns:1fr 1fr}
  .trust{grid-template-columns:1fr}
}
@media (max-width:860px){
  .hdr__cta .btn{display:none}
  .mbar{display:block}
  body{padding-bottom:78px}
  .sys__svg{display:none}
  .sys-mobile{display:block}
  .sys-detail{display:none}
}
@media (max-width:720px){
  :root{--pad:clamp(52px,9vw,72px)}
  body{font-size:16.5px}
  .prob-grid,.cases,.quotes,.metrics,.fit,.skills,.stats{grid-template-columns:1fr}
  .cmp{grid-template-columns:1fr;gap:16px}
  .cmp__mid{padding:2px 0}
  .cmp__arrow{transform:rotate(90deg)}
  .logos{grid-template-columns:repeat(3,1fr)}
  .tl__head{grid-template-columns:44px 1fr auto;gap:14px;padding:20px 0}
  .tl__content{grid-template-columns:44px 1fr;gap:14px}
  .funnel__row{grid-template-columns:1fr;gap:6px}
  .funnel__bar{height:36px}
  .ftr__grid{grid-template-columns:1fr;gap:30px}
  .ftr__bot{flex-direction:column;gap:10px}
}
@media (prefers-reduced-motion:reduce){
  *{animation-duration:.01ms !important;animation-iteration-count:1 !important;transition-duration:.01ms !important}
  html{scroll-behavior:auto}
  .rv{opacity:1;transform:none}
}

/* ============================================================
   TEMA KAIPI IMPULSA — tipografía y bloques invertidos
   ============================================================ */
body{background:var(--paper);color:var(--ink)}

h1,h2,.tl__t,.sys-detail h3,.brand__name,.pull{
  font-family:var(--display);font-weight:400;text-transform:uppercase;letter-spacing:.005em;
}
h1{line-height:.9;font-size:clamp(44px,6vw,82px)}
h2{line-height:.94;font-size:clamp(30px,4vw,50px);max-width:17ch}
h2.wide{max-width:22ch}
.pull{font-size:clamp(21px,2vw,27px);line-height:1.06}
.tl__t{line-height:1;font-size:clamp(20px,2vw,27px);letter-spacing:.01em}
.sys-detail h3{line-height:.96;font-size:clamp(28px,2.8vw,40px)}
.brand__name{font-size:19px;letter-spacing:.02em}
.stat b{font-family:var(--display);font-weight:400}
h3,.faq__q,.panel h3,.metric h3,.case h3,.fit__col h3,.cmp__title,.sys-step h4,.quote__who b{
  font-family:var(--body);font-weight:700;letter-spacing:-.02em;text-transform:none
}
.panel h3{font-size:clamp(21px,2.1vw,28px);line-height:1.14}
.eyebrow,.num,.figure__cap,.panel__label,.tl__n,.metric b,.case__row span,.tl__deliver span,
.stat span,.logo-slot,.funnel__row span,.quote__who span,.ftr h4,.ftr__bot,.micro,.brand__sub,
.panel__slot,.case__media span,.team__media span,.sys-detail__n,.sys-detail__meta,.cmp__tag{
  font-family:var(--body);font-weight:600
}
.hero h1 em{color:var(--accent)}
.hero h1 em::after{display:none}
.brand__mark{display:none}
.brand{gap:0}

/* cabecera y barras */
.hdr{background:rgba(30,29,27,.86)}
.mbar{background:rgba(30,29,27,.94);border-top-color:var(--line)}

/* superficies */
.figure{background:var(--paper-2);border-color:var(--line);box-shadow:none}
.sec--tint .figure{background:var(--paper)}
.panel,.case,.quote,.metric,.prob,.cmp__col,.logo-slot{background:var(--paper-2)}
.sec--tint .panel,.sec--tint .case,.sec--tint .quote,.sec--tint .metric,
.sec--tint .prob,.sec--tint .cmp__col,.sec--tint .logo-slot,.sec--tint .skill{background:var(--paper)}
.prob:hover,.metric:hover{background:var(--chip)}
.sec--tint .prob:hover,.sec--tint .metric:hover{background:var(--paper-2)}
.cmp__col--now{background:var(--paper)}
.sec--tint .cmp__col--now{background:var(--paper-2)}
.cmp__col--new{border-color:var(--accent)}
.cmp__col--new li{background:var(--chip)}
.cmp__arrow{background:var(--accent)}
.cmp__arrow svg{stroke:var(--on-accent)}
.chips li,.tl__deliver,.case__res div,.funnel__bar,.team__media,.stat,.quote__av{background:var(--chip);border-color:var(--line)}
.funnel__fill{background:var(--ink-2)}
.funnel__row:last-child .funnel__fill{background:var(--accent)}
.pull{background:var(--accent);color:var(--on-accent)}
.pull b{color:var(--on-accent);opacity:.72}
.tl__plus svg{stroke:var(--ink)}
.faq__ic svg{stroke:var(--ink)}
.logo-slot,.panel__slot,.case__media span,.team__media span{color:var(--muted)}
.panel__slot svg,.case__media svg,.team__media svg{stroke:var(--muted)}
.notice{background:var(--paper-2)}
.sec--tint .notice{background:var(--paper)}

/* encaje: la columna afirmativa pasa a lima */
.fit__col--yes{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}
.fit__col--yes li{border-top-color:rgba(26,26,18,.18)}
.fit__col--yes li svg{stroke:var(--on-accent)}
.fit__col--yes .dot{background:var(--on-accent)}
.fit__col--yes .dot::after{border-color:rgba(26,26,18,.45)}
.fit__col--no{background:var(--paper-2)}
.sec--tint .fit__col--no{background:var(--paper)}

/* sistema */
.node text{fill:var(--ink)}
.node rect{fill:var(--chip);stroke:var(--line-2)}
.node:hover rect,.node.is-on rect{fill:var(--accent);stroke:var(--accent)}
.node:hover text,.node.is-on text,.node.is-on .node__n{fill:var(--on-accent)}
.sys-loop{color:var(--ink)}
.sys-step__n{background:var(--chip);border-color:var(--line-2)}

/* bloque invertido crema (sistema y CTA final) */
.sec--dark{
  background:var(--dark);color:#1E1D1B;
  --paper:#F1EEE4;--paper-2:#FAF8F1;--chip:#FFFFFF;
  --ink:#1E1D1B;--ink-2:#3B382F;--muted:#6B675C;
  --line:#DFDACB;--line-2:#CBC5B3;
  --dark-2:#FAF8F1;--dark-line:#DFDACB;--dark-muted:#6B675C;
  --accent-text:#5E7A0C;--accent-line:rgba(94,122,12,.4);
}
.sec--dark .eyebrow{color:var(--accent-text)}
.sec--dark .eyebrow::before{background:var(--accent-text)}
.sec--dark .feedback,.sec--dark .ring-flow{stroke:var(--accent-text)}
.sec--dark .sys-detail{border-left-color:var(--accent-text)}
.sec--dark .sys-detail__n,.sec--dark .micro{color:var(--accent-text)}
.sec--dark .micro svg{stroke:var(--accent-text)}
.sec--dark .sys-loop{border-color:var(--accent-text)}
.sec--dark .sys-step:last-child::before{background:linear-gradient(var(--accent-text),transparent)}
.sec--dark .figure{background:#FAF8F1;border-color:#DFDACB}
.sec--dark .btn{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}
.sec--dark .btn--ghost{background:transparent;color:#1E1D1B;border-color:#CBC5B3}
.sec--dark .ring{stroke:#CBC5B3}
.sec--dark .sys-step__n{background:#FFF;border-color:#DFDACB}
.cta-final::before{background:radial-gradient(closest-side,rgba(201,220,79,.35),transparent 70%)}
.hero::after{background:radial-gradient(closest-side,var(--accent-soft),transparent 70%)}

/* footer */
.ftr{background:#171614;border-top-color:#2B2925;color:var(--ink)}
.ftr h4{color:var(--muted)}
.ftr ul a{color:var(--ink-2)}
.ftr__brand p{color:var(--muted)}
.ftr__bot{border-top-color:#2B2925;color:var(--muted)}
.video-slot{
  position:relative;aspect-ratio:16/9;border-radius:var(--r-lg);overflow:hidden;
  background:linear-gradient(155deg,var(--paper-2) 0%,var(--chip) 100%);
  border:1px solid var(--line-2);display:grid;place-items:center;
}
.video-slot::before{
  content:"";position:absolute;inset:14px;border:1px dashed var(--line-2);border-radius:16px;pointer-events:none;
}
.video-slot__badge{
  position:absolute;top:24px;left:26px;display:flex;align-items:center;gap:9px;
  font-size:11px;font-weight:600;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);
}
.video-slot__play{
  width:92px;height:92px;border-radius:50%;background:var(--accent);display:grid;place-items:center;
  transition:transform .2s ease;position:relative;
}
.video-slot__play::after{
  content:"";position:absolute;inset:-14px;border-radius:50%;border:1px solid var(--accent-line);
  animation:pulse 2.8s ease-out infinite;
}
.video-slot__play svg{width:30px;height:30px;fill:var(--on-accent);margin-left:5px}
.video-slot__play:hover{transform:scale(1.06)}
.video-slot__foot{
  position:absolute;left:0;right:0;bottom:0;display:flex;justify-content:space-between;gap:16px;
  padding:16px 26px;font-size:11px;font-weight:600;letter-spacing:.13em;text-transform:uppercase;
  color:var(--muted);background:linear-gradient(transparent,rgba(0,0,0,.35));
}
.video-slot__foot b{color:var(--ink);font-weight:600}
.video-slot video,.video-slot iframe{position:absolute;inset:0;width:100%;height:100%;border:0;object-fit:cover}
.hero__visual .small{margin-top:14px;text-align:right}


/* ---------- PRUEBA: vídeo a sangre en hero + fondo de vídeo en CTA ---------- */
.bleed{--gutter:calc((100vw - min(100vw - 40px, var(--max))) / 2)}
.hero__visual.bleed{
  position:relative;margin-right:calc(-1 * var(--gutter));
  min-height:min(70vh,600px);border-radius:var(--r-lg) 0 0 var(--r-lg);overflow:hidden;
  background:linear-gradient(150deg,#2E2C27,#1A1917);border:1px solid var(--line-2);border-right:0;
}
.bleed video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.bleed::after{
  content:"";position:absolute;inset:0;pointer-events:none;
  background:linear-gradient(90deg,rgba(30,29,27,.6),transparent 42%);
}
.vph{position:absolute;inset:0;display:grid;place-content:center;justify-items:center;gap:10px;text-align:center;padding:28px}
.vph svg{width:40px;height:40px;stroke:var(--line-2);fill:none;stroke-width:1.3}
.vph b{font-size:13px;font-weight:600;color:var(--ink-2)}
.vph span{font-size:11px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);max-width:30ch;line-height:1.6}
.vtag{
  position:absolute;left:24px;top:24px;z-index:2;display:inline-flex;align-items:center;gap:9px;
  padding:9px 14px;border-radius:100px;background:rgba(18,17,15,.45);backdrop-filter:blur(8px);
  border:1px solid rgba(255,255,255,.1);
  font-size:10.5px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--ink);
}
.cta-video{position:relative;isolation:isolate;background:var(--paper);color:var(--ink)}
.cta-video__bg{position:absolute;inset:0;z-index:-1;overflow:hidden;background:linear-gradient(150deg,#2E2C27,#151412)}
.cta-video__bg video{width:100%;height:100%;object-fit:cover}
.cta-video__bg::after{
  content:"";position:absolute;inset:0;
  background:linear-gradient(95deg,rgba(18,17,15,.93) 20%,rgba(18,17,15,.66) 70%);
}
@media (max-width:1080px){
  .hero__visual.bleed{min-height:0;aspect-ratio:16/10}
}
@media (max-width:720px){
  .hero__visual.bleed{aspect-ratio:4/3;border-radius:var(--r-lg) 0 0 var(--r-lg)}
}

/* ---------- por qué Kaipi Impulsa ---------- */
.why{display:grid;gap:clamp(52px,6vw,92px)}
.why__row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(30px,4vw,64px);align-items:center}
.why__row:nth-child(even) .why__media{order:-1}
.why__row > div{min-width:0}
.why__n{
  display:inline-flex;align-items:center;gap:10px;font-size:11px;font-weight:600;
  letter-spacing:.16em;text-transform:uppercase;color:var(--accent);margin-bottom:16px;
}
.why__n::before{content:"";width:22px;height:1px;background:var(--accent)}
.why__t{
  font-family:var(--display);font-weight:400;text-transform:uppercase;letter-spacing:.01em;
  font-size:clamp(23px,2.7vw,36px);line-height:1.05;max-width:30ch;margin-bottom:18px;
}
.why__row p{font-size:16px;line-height:1.6;color:var(--muted);max-width:50ch}
.why__row p + p{margin-top:14px}
.why__kicker{font-size:16px !important;line-height:1.4 !important;font-weight:600;color:var(--ink-2) !important;margin:0 0 10px !important}
.why__row .btn{margin-top:26px}
.why__media{
  position:relative;aspect-ratio:4/3;border-radius:var(--r-lg);border:1px dashed var(--line-2);
  background:var(--paper);display:grid;place-items:center;gap:10px;text-align:center;padding:26px;
}
.sec--tint .why__media{background:var(--paper-2)}
.why__media svg{width:32px;height:32px;stroke:var(--muted);fill:none;stroke-width:1.4}
.why__media svg.levers{width:100%;height:auto;max-width:540px;stroke:none}
.why__media span{font-size:11px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);max-width:28ch;line-height:1.6}
.why__media--photo{padding:0;overflow:hidden;border-style:solid;background:var(--paper-2);}
.why__media--photo img{width:100%;height:100%;display:block;object-fit:cover;object-position:center 72%;}
.why__media--photo img[src="assets/img/kaipi-dashboard-analitica.jpg"]{object-position:32% 46%;}
.why__media.why__media--collage{
  aspect-ratio:3/2;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));
  gap:12px;place-items:stretch;padding:0;border:0;border-radius:0;
  background:transparent;overflow:visible;
}
.why__media--collage .prod-frame{
  width:100%;height:100%;min-width:0;
  background-image:url("data:image/png;base64,");
  background-repeat:no-repeat;background-size:auto 108.654%;
  background-position:var(--photo-x) 48.61%;
}
.why__media--collage .prod-frame:first-child{--photo-x:3.553%;border-radius:var(--r-lg) 0 0 var(--r-lg)}
.why__media--collage .prod-frame:nth-child(2){--photo-x:50.52%}
.why__media--collage .prod-frame:last-child{--photo-x:96.88%;border-radius:0 var(--r-lg) var(--r-lg) 0}
@media(max-width:860px){.why__media.why__media--collage{aspect-ratio:16/10;gap:8px}}
.why__media--photo img[src="assets/img/kaipi-alcance-pizarra.png"]{object-position:58% 42%;}
.why__row:first-child .why__media--photo{transform:none;}
@media (max-width:860px){.why__row:first-child .why__media--photo{transform:none;}}
.why__media--plain{border-style:solid;padding:clamp(22px,2.6vw,34px);place-items:stretch;aspect-ratio:auto}
.why__media.sysboard{border:0;background:transparent;padding:0}
.fnl-mini{display:grid;gap:6px;align-content:center;width:100%}
.fnl-mini .fnl__band{min-height:56px}
.fnl-mini__foot{margin-top:14px;font-size:12.5px;color:var(--muted);text-align:center}
@media (max-width:860px){
  .why__row{grid-template-columns:minmax(0,1fr);gap:26px}
  .why__row:nth-child(even) .why__media{order:0}
  .why__media{aspect-ratio:16/10}
}

/* ---------- titular con palabra rotativa ---------- */
.rot{display:block;position:relative;height:1em;line-height:1;color:var(--accent)}
.rot i{
  position:absolute;left:0;top:0;font-style:normal;white-space:nowrap;
  opacity:0;transform:translateY(.42em);
  transition:opacity .5s ease,transform .5s cubic-bezier(.2,.7,.2,1);
}
.rot i.is-on{opacity:1;transform:none}
.rot i.is-out{opacity:0;transform:translateY(-.42em)}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}

/* Qué hacemos: titular en 2 líneas manteniendo la palabra rotativa */
#que-hacemos .sec-head{max-width:none}
#que-hacemos .qh-title{max-width:none}
#que-hacemos .qh-title__line{display:block}
#que-hacemos .qh-title .rot{
  display:block;width:5.4em;max-width:100%;
}
#que-hacemos .qh-title__line2,
#que-hacemos .qh-title__line3{
  display:block;color:var(--ink);white-space:nowrap;
}
@media (max-width:860px){
  #que-hacemos .qh-title .rot{width:100%;margin-bottom:.04em}
  #que-hacemos .qh-title__line2,
  #que-hacemos .qh-title__line3{white-space:normal}
}

/* ---------- dudas y dolores (paneles con giro) ---------- */
.pains{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.pain{display:block;width:100%;perspective:1200px;height:230px;cursor:pointer;background:none;border:0;padding:0;text-align:left;font:inherit;color:inherit}
.pain__in{
  display:block;position:relative;width:100%;height:100%;transform-style:preserve-3d;
  transition:transform .62s cubic-bezier(.4,.2,.2,1);
}
.pain:hover .pain__in,.pain:focus-visible .pain__in,.pain.is-flipped .pain__in{transform:rotateY(180deg)}
.pain__face{
  position:absolute;inset:0;backface-visibility:hidden;-webkit-backface-visibility:hidden;
  border:1px solid var(--line);border-radius:var(--r);overflow:hidden;
  padding:26px 22px;display:grid;align-content:center;justify-items:start;gap:14px;
}
.pain__face--front{background:var(--paper)}
.sec--tint .pain__face--front{background:var(--paper)}
.pain__face--front::before{content:"";position:absolute;top:0;left:0;right:0;height:3px;background:var(--accent)}
.pain__face--front p{font-size:15.5px;line-height:1.45;font-weight:600;letter-spacing:-.01em}
.pain__hint{
  font-size:10px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;
  color:var(--muted);display:inline-flex;align-items:center;gap:6px;
}
.pain__face--back{
  transform:rotateY(180deg);background:var(--accent);border-color:var(--accent);color:var(--on-accent);
}
.pain__face--back em{font-style:normal;font-size:10px;font-weight:700;letter-spacing:.15em;text-transform:uppercase;opacity:.6}
.pain__face--back p{font-size:16px;line-height:1.45;font-weight:600;letter-spacing:-.01em}
.pains-foot{
  display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:16px 22px;
  margin-top:34px;text-align:center;
}
.pains-foot p{font-size:16px;color:var(--muted)}
@media (max-width:1080px){.pains{grid-template-columns:repeat(2,1fr)}}
@media (max-width:640px){.pains{grid-template-columns:1fr}.pain{height:200px}}


/* ---------- anillo del sistema + ficha de fase ---------- */
.sysview{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(28px,3.5vw,56px);align-items:center}
.ringwrap{position:relative;max-width:560px;margin-inline:auto;width:100%}
.node{cursor:pointer}
.node path{
  fill:var(--accent);fill-opacity:var(--op,.2);stroke:var(--accent);stroke-opacity:.45;stroke-width:1.5;
  transition:fill-opacity .22s ease,stroke-opacity .22s ease;
}
.node:hover path,.node.is-on path{fill-opacity:1;stroke-opacity:1}
.node .node__n{font-family:var(--body);font-size:15px;font-weight:700;fill:var(--ink);text-anchor:middle;opacity:.55}
.node:hover .node__n,.node.is-on .node__n{opacity:1}
.node .node__lbl{font-family:var(--body);font-size:14.5px;font-weight:700;letter-spacing:-.01em;fill:var(--ink)}
.sys-core{
  position:absolute;left:50%;top:48.5%;transform:translate(-50%,-50%);
  width:38%;text-align:center;display:grid;gap:6px;justify-items:center;
}
.sys-core b{font-family:var(--display);font-weight:400;text-transform:uppercase;font-size:clamp(16px,1.7vw,22px);line-height:.95}
.sys-core span{font-size:10.5px;font-weight:600;letter-spacing:.15em;text-transform:uppercase;color:var(--muted)}

.syscard{
  position:relative;overflow:hidden;border-radius:var(--r-lg);
  background:var(--dark-2);color:var(--ink);
  border:1px solid var(--dark-line);border-left:3px solid var(--accent);
  padding:clamp(32px,3.6vw,48px) clamp(26px,3vw,40px);text-align:center;
  min-height:330px;display:grid;align-content:center;justify-items:center;
}
.syscard__n{
  position:absolute;right:16px;bottom:-14px;font-family:var(--display);font-weight:400;
  font-size:clamp(96px,11vw,150px);line-height:.8;color:rgba(94,122,12,.11);pointer-events:none;
}
.syscard__in{display:grid;justify-items:center;gap:16px;position:relative;z-index:1}
.syscard.is-swap .syscard__in{animation:swapIn .4s ease}
@keyframes swapIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
.syscard__ic{width:48px;height:48px;border-radius:50%;background:var(--accent);display:grid;place-items:center}
.syscard__ic svg{width:22px;height:22px;stroke:#1E1D1B;fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.syscard h3{
  font-family:var(--display);font-weight:400;text-transform:uppercase;letter-spacing:.01em;
  font-size:clamp(24px,2.9vw,36px);line-height:.98;max-width:14ch;
}
.syscard p{font-size:16px;line-height:1.55;color:var(--dark-muted);max-width:32ch}
.syscard__tag{font-size:10.5px;font-weight:600;letter-spacing:.16em;text-transform:uppercase;color:var(--accent-text)}
@media (max-width:860px){.sysview{display:none}}

/* ---------- banda de confianza dentro del hero ---------- */
.trustbar{
  position:relative;z-index:1;margin-top:clamp(38px,4.6vw,68px);
  padding-top:clamp(26px,3vw,38px);border-top:1px solid var(--line);
}
.marquee{
  position:relative;overflow:hidden;
  -webkit-mask:linear-gradient(90deg,transparent,#000 7%,#000 93%,transparent);
  mask:linear-gradient(90deg,transparent,#000 7%,#000 93%,transparent);
}
.marquee__track{display:flex;align-items:center;gap:clamp(44px,5.5vw,84px);width:max-content;
  animation:marquee 38s linear infinite}
.marquee:hover .marquee__track{animation-play-state:paused}
@keyframes marquee{to{transform:translateX(-50%)}}
.marquee__track .logo-mark{
  flex:0 0 auto;display:block;height:38px;width:auto;
  background:var(--ink);opacity:.55;transition:opacity .2s;
  -webkit-mask-image:var(--m);mask-image:var(--m);
  -webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;
  -webkit-mask-position:center;mask-position:center;
  -webkit-mask-size:contain;mask-size:contain;
}
.marquee__track .logo-mark:hover{opacity:.95}
.figband{padding-block:clamp(50px,5.6vw,88px)}
.figs{display:grid;grid-template-columns:repeat(3,1fr);gap:0;justify-items:stretch;text-align:center}
.tfig{
  position:relative;display:grid;justify-items:center;align-content:center;
  padding-inline:clamp(24px,4vw,64px);min-height:150px;
}
.tfig:not(:last-child)::after{
  content:"";position:absolute;right:0;top:16%;bottom:16%;width:1px;
  background:linear-gradient(to bottom,transparent,var(--line-2) 22%,var(--line-2) 78%,transparent);
  opacity:.72;
}
.tfig b{
  display:block;font-family:var(--display);font-weight:400;color:var(--accent);
  font-size:clamp(48px,7vw,88px);line-height:.92;letter-spacing:.01em;
  font-variant-numeric:tabular-nums;
}
.tfig span{
  display:block;margin-top:6px;font-size:15px;line-height:1.42;color:var(--ink-2);max-width:19ch;
  opacity:0;transform:translateY(6px);
  transition:opacity .45s ease,transform .45s cubic-bezier(.2,.7,.2,1);
}
.figs.is-in .tfig span{opacity:1;transform:none}
.figs.is-in .tfig:nth-child(1) span{transition-delay:.28s}
.figs.is-in .tfig:nth-child(2) span{transition-delay:.40s}
.figs.is-in .tfig:nth-child(3) span{transition-delay:.52s}
@media (prefers-reduced-motion:reduce){
  .marquee__track{animation:none;flex-wrap:wrap;justify-content:center;width:100%}
  .tfig span{opacity:1;transform:none;transition:none}
}
@media (max-width:720px){
  .marquee__track .logo-mark{height:30px}
  .figs{grid-template-columns:1fr;gap:22px}
  .tfig{min-height:0;padding:18px 0 26px}
  .tfig:not(:last-child)::after{right:18%;left:18%;top:auto;bottom:0;width:auto;height:1px}
}

/* ---------- embudo por tramos (métricas) ---------- */
.fnl{display:grid;grid-template-columns:minmax(150px,.85fr) 1.15fr;column-gap:22px;row-gap:6px;align-items:stretch}
.fnl__band{
  position:relative;display:grid;place-items:center;text-align:center;min-height:74px;padding:0 10px;
}
.fnl__band b{display:block;font-size:15px;font-weight:700;letter-spacing:-.02em;line-height:1.2}
.fnl__band span{display:block;margin-top:3px;font-size:11px;color:var(--muted);line-height:1.3}
.fnl__band--1{clip-path:polygon(0 0,100% 0,93% 100%,7% 100%);background:rgba(201,220,79,.09)}
.fnl__band--2{clip-path:polygon(7% 0,93% 0,86% 100%,14% 100%);background:rgba(201,220,79,.13)}
.fnl__band--3{clip-path:polygon(14% 0,86% 0,79% 100%,21% 100%);background:rgba(201,220,79,.18)}
.fnl__band--4{clip-path:polygon(21% 0,79% 0,73% 100%,27% 100%);background:rgba(201,220,79,.24)}
.fnl__band--5{clip-path:polygon(27% 0,73% 0,73% 100%,27% 100%);background:var(--accent);color:var(--on-accent)}
.fnl__band--5 span{color:var(--on-accent);opacity:.72}
.fnl__leak{display:flex;flex-direction:column;justify-content:center;gap:7px;padding:10px 0 10px 18px;
  border-left:1.5px dashed var(--line-2)}
.fnl__leak em{font-style:normal;font-size:10px;font-weight:600;letter-spacing:.13em;text-transform:uppercase;color:var(--accent);line-height:1.4}
.fnl__leak p{font-size:14px;line-height:1.45;color:var(--ink-2)}
.fnl__metric{display:inline-flex;align-items:baseline;gap:8px;align-self:flex-start;font-size:12.5px;color:var(--muted)}
.fnl__metric i{font-style:normal;font-weight:700;color:var(--accent);font-size:11px;letter-spacing:.06em}
.fnl__metric b{font-weight:600;color:var(--ink)}
.fnl__leak--end{border-left:0;border:1px solid var(--accent);border-radius:var(--r);background:var(--accent-soft);padding:16px 18px;gap:5px}
.fnl__leak--end strong{font-size:15.5px;font-weight:700;letter-spacing:-.02em}
.fnl__leak--end p{font-size:13.5px;color:var(--muted)}
.fnl__note{grid-column:1 / -1;display:flex;gap:9px;align-items:flex-start;margin-top:14px;font-size:12.5px;line-height:1.5;color:var(--muted)}
@media (max-width:860px){
  .fnl{grid-template-columns:1fr;row-gap:0}
  .fnl__band{min-height:64px}
  .fnl__leak{margin-left:14px;padding:14px 0 22px 18px}
  .fnl__leak--end{margin-left:0}
}

/* ---------- flujo de trabajo (serpiente conectada) ---------- */
.flow{--fgap:30px;--fbadge:40px;--frowpad:64px;--felbow:34px;padding-inline:var(--felbow);position:relative}
.flow__wires{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none;z-index:0}
.flow__wires path{fill:none;stroke:#777568;stroke-width:2.5;vector-effect:non-scaling-stroke;stroke-linecap:round;stroke-linejoin:round}
.flow__row{
  position:relative;z-index:1;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--fgap);
  padding-bottom:var(--frowpad);
}
.flow__row::before,.flow__row--down-r::after,.flow__row--down-l::after{display:none!important}
.flow__row--rev{direction:rtl}
.flow__row--rev .step{direction:ltr}
.step{position:relative;z-index:1}
/* Alineación vertical uniforme de los pasos en escritorio: títulos y entregables comparten línea */
@media (min-width:981px){
  .flow__row .step{
    display:grid;
    grid-template-rows:auto 46px 1fr auto;
    align-self:stretch;
  }
  .flow__row .step h3{align-self:start;margin-bottom:10px}
  .flow__row .step > p:not(.step__out){align-self:start}
  .flow__row .step .step__out{align-self:end}
}
.step__badge{
  position:relative;z-index:2;width:var(--fbadge);height:var(--fbadge);border-radius:11px;
  background:var(--accent);color:var(--on-accent);display:grid;place-items:center;
  font-weight:700;font-size:15px;margin-bottom:20px;
}
.step h3{font-size:18px;line-height:1.25;margin-bottom:10px}
.step p{font-size:15px;line-height:1.6;color:var(--muted);max-width:34ch}
.step__out{margin-top:14px;font-size:13.5px;line-height:1.55;color:var(--ink-2)}
.step__out b{
  display:block;font-size:10.5px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;
  color:var(--accent);margin-bottom:4px;
}
.flow__end{
  position:relative;z-index:1;margin:0 auto;
  width:fit-content;max-width:calc(100% - 72px);
  display:grid;grid-template-columns:var(--fbadge) minmax(0,50ch) minmax(220px,24ch);column-gap:18px;row-gap:18px;align-items:start;justify-content:start;
  padding:28px 22px 28px 28px;border:1px solid var(--accent);border-radius:var(--r-lg);background:var(--accent-soft);
}
.flow__end .step p{max-width:50ch}
.flow__loop{max-width:24ch;border-left:2px solid var(--accent);padding-left:16px;font-size:14px;line-height:1.55;color:var(--ink)}
.flow__loop b{display:block;font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--accent);margin-bottom:6px}
@media (max-width:980px){
  .flow{padding-inline:0}
  .flow__row{grid-template-columns:1fr 1fr;gap:var(--fgap) 24px}
  .flow__row::before,.flow__row--down-r::after,.flow__row--down-l::after{display:none}
  .flow__row--rev{direction:ltr}
  .flow__end{margin-inline:0;width:100%;max-width:100%;grid-template-columns:var(--fbadge) 1fr}
  .flow__loop{grid-column:2}
}
@media (max-width:720px){
  .flow__row{grid-template-columns:1fr;gap:0;padding-bottom:0}
  .step{position:relative;padding-left:58px;padding-bottom:30px}
  .step__badge{position:absolute;left:0;top:0;margin:0}
  .step::before{content:"";position:absolute;left:20px;top:46px;bottom:0;width:2.5px;background:#777568}
  .step p{max-width:none}
  .flow__end{width:100%;max-width:100%;grid-template-columns:1fr;padding:24px;gap:16px}
  .flow__end .step{padding-left:0;padding-bottom:0}
  .flow__end .step::before{display:none}
  .flow__end .step__badge{position:static;margin:0}
  .flow__loop{grid-column:auto;margin-top:4px}
}

.tab-btn:hover,.sec--tint .tab-btn:hover{background:var(--chip);color:var(--ink)}
.sec--tint .tab-btn.is-active{background:var(--paper-2);border-color:var(--line-2)}
.tab-btn.is-active{background:var(--paper-2);box-shadow:none;border-color:var(--line-2)}
.tab-btn.is-active i{color:var(--accent)}
.quote p{color:var(--ink)}
.case__res div{color:var(--muted)}
.hero__note,.funnel__note,.notice,.small.muted{color:var(--muted)}

/* ---------- hero compacto: el carrusel entra en la primera pantalla ---------- */
.hero{padding-top:clamp(24px,2.8vw,44px);padding-bottom:clamp(28px,3.2vw,46px)}
.hero .eyebrow{margin-bottom:14px}
.hero h1{font-size:clamp(37px,4.5vw,63px);margin-bottom:20px}
.hero .lead{font-size:clamp(16px,1.15vw,18.5px)}
.hero__cta{margin-top:26px}
.hero .btn{min-height:50px}
.hero__note{margin-top:16px;font-size:13.5px}
.hero__visual.bleed{min-height:min(54vh,470px)}
.trustbar{margin-top:clamp(24px,2.8vw,40px);padding-top:clamp(18px,2.2vw,28px)}
.marquee__track .logo-mark{height:34px}
@media (max-width:1080px){
  .hero__visual.bleed{min-height:0;aspect-ratio:16/9}
}

/* ---------- el hero ocupa exactamente la primera pantalla ---------- */
