/* ---------- los logos, más pegados a la línea divisoria ---------- */
.trustbar{padding-top:clamp(14px,1.6vw,20px)}
.marquee{margin-top:2px}
.hero{padding-bottom:clamp(28px,3.2vw,46px)}
@media (max-width:1080px){.hero{padding-bottom:clamp(26px,3vw,40px)}}

/* ---------- v25: vídeo a pantalla completa en el above the fold ---------- */
.hero--video{
  isolation:isolate;
  background:#151412;
}
.hero--video::after{display:none}
.hero__bg{
