    linear-gradient(90deg,rgba(20,19,17,.91) 0%,rgba(20,19,17,.79) 39%,rgba(20,19,17,.43) 68%,rgba(20,19,17,.28) 100%),
    linear-gradient(0deg,rgba(20,19,17,.72) 0%,rgba(20,19,17,.06) 31%,rgba(20,19,17,.12) 100%);
}
.hero--video .hero__grid{
  grid-template-columns:minmax(0,780px) 1fr;
  width:min(calc(100% - 40px),var(--max));
}
.hero--video .hero__copy{
