/* ---------- v27: Qué hacemos, todo visible en una sola lectura ---------- */
#que-hacemos{padding-block:clamp(56px,5.3vw,82px)}
#que-hacemos .sec-head{max-width:1040px;margin-bottom:clamp(30px,3.2vw,42px)}
#que-hacemos .sec-head .lead{margin-top:16px}
.qh-services{
  display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:1px;
  border:1px solid var(--line);border-radius:var(--r-lg);overflow:hidden;
  background:var(--line);
}
.qh-service{
  position:relative;background:var(--paper-2);padding:24px 20px 25px;
  min-width:0;display:flex;flex-direction:column;
  transition:background .22s ease,transform .22s ease;
}
.qh-service::before{
  content:"";position:absolute;left:0;right:0;top:0;height:3px;background:var(--accent);
  transform:scaleX(.28);transform-origin:left;opacity:.82;
  transition:transform .25s ease,opacity .25s ease;
}
.qh-service:hover{background:var(--chip)}
.qh-service:hover::before{transform:scaleX(1);opacity:1}
.qh-service__head{min-height:76px;padding-top:5px}
.qh-service__n{
  display:block;margin-bottom:10px;font-size:10.5px;font-weight:700;line-height:1;
  letter-spacing:.14em;color:var(--accent);
}
.qh-service h3{font-size:17px;line-height:1.18;max-width:15ch}
.qh-service__result{
  min-height:84px;margin:17px 0 19px;padding-top:17px;border-top:1px solid var(--line);
  color:var(--ink-2);font-size:14.5px;font-weight:600;line-height:1.42;letter-spacing:-.01em;
}
.qh-service__list{list-style:none;margin:0;padding:0}
.qh-service__list li{
  position:relative;padding:0 0 0 18px;margin-top:13px;
  color:var(--muted);font-size:13.25px;line-height:1.32;
}
.qh-service__list li::before{
  content:"";position:absolute;left:1px;top:.64em;width:6px;height:6px;
  border-top:1.5px solid var(--accent);border-right:1.5px solid var(--accent);
  transform:translateY(-50%) rotate(45deg);
}
.qh-service__list li:first-child{margin-top:0}
@media (max-width:1120px){
  .qh-services{grid-template-columns:repeat(3,1fr)}
  .qh-service__result{min-height:68px}
}
@media (max-width:760px){
  #que-hacemos{padding-block:54px}
  .qh-services{grid-template-columns:1fr}
  .qh-service{padding:23px 22px}
  .qh-service__head,.qh-service__result{min-height:0}
  .qh-service h3{max-width:none;font-size:18px}
  .qh-service__result{margin:14px 0 14px}
}


/* ---------- plataformas publicitarias ---------- */
.why__platlead{margin-top:28px !important;margin-bottom:14px;max-width:50ch}
.qh-plat{
  --plat-gap:42px;
  position:relative;width:100%;max-width:50ch;padding:6px 0 4px;
  overflow:hidden;
}
.qh-plat::before,
.qh-plat::after{content:"";position:absolute;top:0;bottom:0;width:38px;z-index:2;pointer-events:none}
.qh-plat::before{left:0;background:linear-gradient(90deg,var(--paper-2) 28%,rgba(35,33,30,0));}
.qh-plat::after{right:0;background:linear-gradient(270deg,var(--paper-2) 28%,rgba(35,33,30,0));}
.qh-plat__track{display:flex;align-items:center;gap:var(--plat-gap);width:max-content;animation:platMarquee 20s linear infinite;will-change:transform}
.qh-plat:hover .qh-plat__track{animation-play-state:paused}
.qh-plat__item{flex:0 0 auto;height:72px;display:flex;align-items:center;justify-content:center;line-height:0}
.qh-plat__item img,.qh-plat__item svg{display:block;max-width:none;width:auto;height:56px;object-fit:contain;vertical-align:middle}
.qh-plat__item--google{margin-right:10px}
.qh-plat__item--google img{height:62px}
.qh-plat__item--meta img{height:66px}
.qh-plat__item--linkedin svg{height:34px}
.qh-plat__item--tiktok img{height:54px}
@keyframes platMarquee{from{transform:translateX(0)}to{transform:translateX(calc(-50% - (var(--plat-gap) / 2)))}}
@media (prefers-reduced-motion:reduce){.qh-plat__track{animation:none;width:auto;flex-wrap:wrap;justify-content:flex-start}}
@media (max-width:640px){
  .why__platlead{margin-top:22px !important}
  .qh-plat{--plat-gap:26px;padding:4px 0 2px}
  .qh-plat::before,.qh-plat::after{width:20px}
  .qh-plat__item{height:56px}
  .qh-plat__item img,.qh-plat__item svg{height:44px}
  .qh-plat__item--google{margin-right:6px}
  .qh-plat__item--google img{height:48px}
  .qh-plat__item--meta img{height:50px}
  .qh-plat__item--linkedin svg{height:27px}
  .qh-plat__item--tiktok img{height:44px}
}

/* ---------- diagrama del sistema Impulsa ---------- */
.sysdiag{display:grid;place-items:center}
.sysdiag .svg-fig{width:100%;height:auto;max-width:520px}
.sysdiag__box rect{fill:var(--chip);stroke:var(--line-2);stroke-width:1.5}
.sysdiag__n{font-family:var(--body);font-size:11px;font-weight:700;letter-spacing:.12em;fill:var(--accent)}
.sysdiag__t{font-family:var(--body);font-size:15px;font-weight:700;letter-spacing:-.01em;fill:var(--ink)}
.sysdiag__hub1{font-family:var(--body);font-size:10px;font-weight:600;letter-spacing:.18em;fill:var(--on-accent);opacity:.65;text-anchor:middle}
.sysdiag__hub2{font-family:var(--display);font-size:22px;letter-spacing:.02em;fill:var(--on-accent);text-anchor:middle}
.sysdiag__foot{font-family:var(--body);font-size:10px;font-weight:600;letter-spacing:.16em;fill:var(--muted);text-anchor:middle}
.sysdiag__flow line{stroke-dasharray:16 200;stroke-dashoffset:0;animation:diagflow 3.2s linear infinite}
@keyframes diagflow{from{stroke-dashoffset:216}to{stroke-dashoffset:0}}
@media (prefers-reduced-motion:reduce){.sysdiag__flow line{animation:none;stroke-dasharray:none;opacity:.5}}

/* ---------- versión alternativa del bloque sistema ---------- */
.sysboard{display:flex;align-items:center;justify-content:center;min-height:100%}
.levers{width:100%;height:auto;max-width:540px;display:block;margin-inline:auto;overflow:visible}

.levers__ring path{fill:none;stroke:var(--line-2);stroke-width:1.5}
.levers__ring path:nth-child(1){stroke:var(--accent);stroke-opacity:.55}

.levers__core{fill:var(--accent)}
.levers__coreLabel{
  font-family:var(--body);font-size:10px;font-weight:700;letter-spacing:.2em;
  fill:var(--on-accent);fill-opacity:.6;text-anchor:middle;
}
.levers__coreName{
  font-family:var(--display);font-size:29px;letter-spacing:.02em;
  fill:var(--on-accent);text-anchor:middle;
}
.levers__coreSub{
  font-family:var(--body);font-size:10.5px;font-weight:600;letter-spacing:.03em;
  fill:var(--on-accent);fill-opacity:.65;text-anchor:middle;
}

.levers__node circle{fill:var(--chip);stroke:var(--line-2);stroke-width:1.5;transition:stroke .25s}
.levers__node .ico{fill:none;stroke:var(--accent);stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round;transition:stroke .25s}
.levers__node--fill .ico{fill:var(--accent);stroke:none}
.levers:hover .levers__node circle{stroke:var(--accent);stroke-opacity:.5}

.levers__n{
  font-family:var(--body);font-size:10.5px;font-weight:700;letter-spacing:.15em;
  fill:var(--accent);
}
.levers__t{
  font-family:var(--display);font-size:21px;letter-spacing:.01em;
  fill:var(--ink);text-transform:uppercase;
}

@media (max-width:520px){
  .levers{max-width:340px}
  .levers__coreName{font-size:25px}
  .levers__t{font-size:18px}
}



/* ---------- v71: legibilidad mínima de texto ---------- */
/* El texto de lectura normal no baja de 16px. Se mantienen más pequeños
   únicamente etiquetas, eyebrows, numeración y micro-labels de interfaz. */
.small,
.btn--sm,
.nav,
.hero__note,
.prob p,
.leak-list li,
.cmp__list li,
.chips li,
.sys-step p,
.sys-loop,
.tl__deliver p,
.metric p,
.funnel__note,
.case__row p,
.case__res div,
.notice,
.skill,
.quote__who b,
.micro,
.ftr ul,
.ftr__brand p,
.pain__face--front p,
.fnl__band b,
.fnl__leak p,
.fnl__metric,
.fnl__leak--end strong,
.fnl__leak--end p,
.fnl__note,
.step p,
.step__out,
.flow__loop,
.qh-service__result,
.qh-service__list li {
  font-size:16px !important;
}

/* Excepción de lectura para los textos explicativos de los pasos 1–7. */
.step > p:not(.step__out){font-size:15px !important;}

/* Textos que ya eran de 16px o más conservan su tamaño actual. */


/* ---------- ciclo del sistema (CTA final) ---------- */
.cycle{display:grid;justify-items:center;gap:14px}
.cycle__svg{width:100%;height:auto;max-width:440px;display:block;overflow:visible}

.cyc__seg path{
  fill:var(--accent);fill-opacity:var(--op,.4);
  stroke:var(--accent);stroke-opacity:.35;stroke-width:1.2;
  transition:fill-opacity .3s ease;
}
.cyc__seg:hover path{fill-opacity:1}
.cyc__n{
  font-family:var(--body);font-size:14px;font-weight:700;letter-spacing:.04em;
  fill:var(--on-accent);text-anchor:middle;
}
.cyc__seg:first-of-type .cyc__n,.cyc__seg:nth-of-type(2) .cyc__n{fill:var(--ink)}
.cyc__seg:hover .cyc__n{fill:var(--on-accent)}
.cyc__lbl{
  font-family:var(--body);font-size:13.5px;font-weight:700;letter-spacing:-.01em;fill:var(--ink);
}

.cyc__hubRing{fill:none;stroke:var(--accent);stroke-opacity:.3;stroke-dasharray:3 8}
.cyc__hub{fill:var(--accent)}
.cyc__hubTop{
  font-family:var(--body);font-size:10.5px;font-weight:700;letter-spacing:.22em;
  fill:var(--on-accent);fill-opacity:.62;text-anchor:middle;
}
.cyc__hubName{
  font-family:var(--display);font-size:33px;letter-spacing:.02em;
  fill:var(--on-accent);text-anchor:middle;
}
.cyc__hubSub{
  font-family:var(--body);font-size:11px;font-weight:600;letter-spacing:.06em;
  fill:var(--on-accent);fill-opacity:.6;text-anchor:middle;
}

.cycle__foot{
  display:flex;align-items:center;gap:9px;
  font-size:12.5px;font-weight:600;letter-spacing:.02em;color:var(--muted);
}
.cycle__loop{
  display:inline-grid;place-items:center;width:22px;height:22px;flex:none;
  border-radius:50%;border:1.5px solid var(--accent);color:var(--accent);font-size:12px;line-height:1;
}
@media (max-width:520px){
  .cycle__svg{max-width:340px}
  .cyc__lbl{font-size:12px}
  .cyc__hubName{font-size:27px}
}


/* ============================================================
   v101 · Revisión de diseño
   Ajustes de jerarquía, tipografía y limpieza visual.
   ============================================================ */

/* Hero: tres líneas controladas en escritorio. */
.hero--video .hero__title{font-size:clamp(44px,5.1vw,74px);max-width:none}
.hero__title-line{display:block;white-space:nowrap}

/* Unificamos el cuerpo de lectura en 16px. Las etiquetas/microcopy y cifras
   mantienen su escala propia para conservar jerarquía funcional. */
.lead,
.hero .lead,
.prob p,
.sys-detail p,
.sys-step p,
.tl__content p,
.tl__deliver p,
.metric p,
.why__row p,
.pain__face--front p,
.pain__face--back p,
.pains-foot p,
.syscard p,
.fnl__leak p,
.fnl__leak--end p,
.step p,
.step__out,
.flow__loop,
.case__summary,
.case__result span,
.quote p,
.faq__a p,
.ftr__brand p,
.qh-service__list li{
  font-size:16px !important;
}

/* Leads de sección algo más contenidos y equilibrados. */
.sec-head .lead{max-width:52ch;text-wrap:balance}
#que-hacemos .sec-head .lead{max-width:48ch}

/* Qué hacemos: titular en dos líneas + menos ruido en las listas. */
#que-hacemos .qh-title__line{
  display:flex;align-items:flex-start;gap:.08em;white-space:nowrap;
}
#que-hacemos .qh-title .rot{
  display:inline-block;flex:0 0 4.9em;width:4.9em;max-width:none;
}
#que-hacemos .qh-title__tail{display:block;color:var(--ink)}
#que-hacemos .qh-title__line2{display:block;color:var(--ink);white-space:nowrap}
.qh-service h3,.step h3{font-size:18px !important}

/* Paso 7: alineado a la izquierda y con el mismo peso visual que el resto. */
.flow__end{
  margin:0;width:100%;max-width:none;
  padding:24px 0 0;
  border:0;border-top:1px solid var(--line);border-radius:0;
  background:transparent;
  justify-content:start;
}
.flow__loop{border-left:1px solid var(--line-2);color:var(--muted)}
@media (min-width:981px){
  .flow__end{grid-template-columns:var(--fbadge) minmax(0,1fr) minmax(230px,28ch)}
}
@media (max-width:980px){
  .flow__end{margin-inline:0;grid-template-columns:var(--fbadge) 1fr}
  .flow__loop{grid-column:2}
}
@media (max-width:720px){
  .hero__title-line{white-space:normal}
  #que-hacemos .qh-title__line{display:block;white-space:normal}
  #que-hacemos .qh-title .rot{display:block;width:100%;max-width:100%;margin-bottom:.04em}
  #que-hacemos .qh-title__line2{white-space:normal}
  .flow__end{grid-template-columns:1fr;padding-top:22px}
  .flow__loop{grid-column:auto}
}

/* Casos: oscurecemos ligeramente la foto y dejamos los logos blancos limpios,
   sin sombras artificiales. */
.case__media img.case__shot{z-index:0}
.case__media::after{
  content:"";position:absolute;inset:0;z-index:1;
  background:rgba(18,17,15,.34);pointer-events:none;
}
.case__logo,.case__logo--vidam{filter:none !important;opacity:1}
.case__summary,.case__result span{font-size:16px !important}


/* Paso 7 centrado; solo el ciclo continuo conserva el fondo iluminado. */
.flow__end{
  width:100%;max-width:760px;margin-inline:auto;
  grid-template-columns:minmax(0,1fr);justify-items:center;gap:18px;
  padding:32px 0 0;border:0;border-radius:0;background:transparent;
  text-align:center;
}
.flow__end > .step__badge{position:static;margin:0;}
.flow__end > .step{width:100%;padding:0;}
.flow__end > .step::before{display:none;}
.flow__end .step p{max-width:64ch;margin-inline:auto;}
.flow__end > .flow__loop{
  grid-column:1;width:100%;max-width:64ch;margin:10px 0 0;
  padding:24px 28px;border:1px solid var(--accent);
  border-radius:var(--r-lg);background:var(--accent-soft);color:var(--ink);
}
.flow__end > .flow__loop b{margin-bottom:10px;}
@media(max-width:720px){
  .flow__end{padding-top:24px;gap:16px;}
  .flow__end > .flow__loop{padding:22px 20px;}
}

/* Conector centrado entre el entregable del paso 7 y el ciclo continuo. */
.flow__end > .flow__loop{position:relative;margin-top:28px;--cycle-connector:38px;}
.flow__end > .flow__loop::before{
  content:"";position:absolute;left:50%;transform:translateX(-50%);
  top:calc(-1 * (var(--cycle-connector) + 1px));
  width:2.5px;height:var(--cycle-connector);background:#777568;
  pointer-events:none;
}
@media(max-width:720px){.flow__end > .flow__loop{--cycle-connector:36px;}}

/* Dos líneas para los titulares de resultados y diagnóstico. */
h2.title-two-lines{max-width:none;}
.title-two-lines > span{display:block;}
.cta-final__grid > div:first-child{min-width:0;container-type:inline-size;}
.cta-final h2.title-two-lines{font-size:clamp(25px,7.1cqi,60px);}
@media(min-width:721px){.title-two-lines > span{white-space:nowrap;}}
/* Titular de diferenciación en una sola línea en escritorio. */
#por-que .sec-head{max-width:none;container-type:inline-size;}
#por-que h2.wide{max-width:none;}
@media(min-width:981px){
  #por-que h2.wide{white-space:nowrap;font-size:clamp(30px,4vw,50px);}
}/* Titular del proceso en dos líneas en escritorio. */
h2.process-title{max-width:none;}
.process-title > span{display:block;}
@media(min-width:721px){.process-title > span{white-space:nowrap;}}

/* Las seis áreas se muestran en una sola fila en escritorio. */
@media (min-width:1121px){
  #que-hacemos .qh-services{grid-template-columns:repeat(6,minmax(0,1fr));}
  #que-hacemos .qh-service{padding-inline:14px;}
  #que-hacemos .qh-service__head{min-height:96px;}
}
@media (min-width:901px) and (max-width:1120px){
  #que-hacemos .qh-services{grid-template-columns:repeat(3,minmax(0,1fr));}
}
@media (min-width:761px) and (max-width:900px){
  #que-hacemos .qh-services{grid-template-columns:repeat(2,minmax(0,1fr));}
}
@media (max-width:760px){
  #que-hacemos .qh-services{grid-template-columns:1fr;}
}

/* Logo oficial: se encuadra el archivo original sin alterarlo. */
.brand__logo{display:block;position:relative;flex:none;width:132px;aspect-ratio:3306/1688;overflow:hidden;}
.brand__logo img{position:absolute;left:-18.06%;top:-83.29%;width:136.12%;height:auto;max-width:none;}
.ftr .brand__logo{width:178px;}
/* ============================================================
   FORMULARIO DE CUALIFICACIÓN (mismo sistema que /kaipimpulsa/)
   Namespace "qf-" para no chocar con .step/.field/.option ya usados
   en el resto de la página (timeline del proceso, etc.)
   ============================================================ */
.qf-card{
  background:var(--paper-2);border:1px solid var(--line);border-radius:var(--r-lg);
  padding:clamp(28px,3.4vw,40px);
}

.qf-progress{height:4px;background:var(--line);border-radius:4px;margin-bottom:26px;overflow:hidden;}
.qf-progress__fill{height:100%;width:0;background:var(--accent);transition:width .4s ease;}

.qf-step{display:none;}
.qf-step.is-active{display:block;animation:qfStepIn .35s ease both;}
@keyframes qfStepIn{from{opacity:0;transform:translateX(14px);}to{opacity:1;transform:translateX(0);}}

h2.qf-step__q{font-family:var(--display);font-weight:700;letter-spacing:-.03em;
  font-size:clamp(25px,2.5vw,32px);line-height:1.08;color:var(--ink);margin-bottom:22px;max-width:none;}
.qf-step__count{font-family:var(--mono);font-size:12px;font-weight:500;letter-spacing:.14em;
  text-transform:uppercase;color:var(--accent);margin-bottom:12px;}
.qf-step__intro{font-family:var(--body);font-weight:600;font-size:19px;line-height:1.35;color:var(--ink);margin-bottom:22px;}

.qf-options{display:flex;flex-direction:column;gap:12px;margin-bottom:26px;}
.qf-option{
  display:flex;align-items:flex-start;gap:13px;
  font-family:var(--body);font-size:16px;line-height:1.4;color:var(--ink-2);
  cursor:pointer;padding:12px 14px;border:1px solid var(--line-2);border-radius:10px;
  transition:border-color .15s ease,background .15s ease;
}
.qf-option:hover{border-color:var(--accent-line);}
.qf-option__box{
  width:18px;height:18px;flex-shrink:0;margin-top:1px;
  border:1px solid var(--line-2);border-radius:4px;background:transparent;
  position:relative;transition:background .15s ease,border-color .15s ease;
}
.qf-option.is-selected{border-color:var(--accent);background:var(--accent-soft);color:var(--ink);}
.qf-option.is-selected .qf-option__box{background:var(--accent);border-color:var(--accent);}
.qf-option.is-selected .qf-option__box::after{
  content:'';position:absolute;left:5px;top:1px;
  width:5px;height:9px;border:solid var(--on-accent);
  border-width:0 2px 2px 0;transform:rotate(45deg);
}

.qf-field{margin-bottom:26px;}
.qf-field input,.qf-field textarea{
  width:100%;background:var(--paper);border:1px solid var(--line-2);color:var(--ink);
  font-family:var(--body);font-size:16px;padding:13px 15px;border-radius:8px;resize:vertical;
}
.qf-field input::placeholder,.qf-field textarea::placeholder{color:var(--muted);}
.qf-field input:focus,.qf-field textarea:focus{outline:none;border-color:var(--accent);}
.qf-field textarea{min-height:120px;}
.qf-field--other{margin-top:12px;display:none;}
.qf-field--other.is-visible{display:block;}
.qf-field-error{color:#E8776B;font-family:var(--body);font-size:13.5px;margin-top:7px;display:none;}
.qf-field-error.is-visible{display:block;}

.qf-consent{display:flex;flex-direction:column;gap:13px;margin-bottom:26px;}
.qf-consent label{display:flex;align-items:flex-start;gap:11px;font-family:var(--body);
  font-size:14px;line-height:1.45;color:var(--ink-2);cursor:pointer;}
.qf-consent a{color:var(--accent);text-decoration:underline;}
.qf-consent input{width:17px;height:17px;flex-shrink:0;margin-top:2px;accent-color:var(--accent);}

.qf-nav{display:flex;align-items:center;justify-content:space-between;gap:16px;}
.qf-btn-back{background:none;border:none;color:var(--muted);font-family:var(--body);font-size:15px;cursor:pointer;padding:10px 0;}
.qf-btn-back:hover{color:var(--ink);}
.qf-btn-back[hidden]{visibility:hidden;}
.qf-btn-next:disabled{opacity:.4;cursor:not-allowed;transform:none;box-shadow:none;}

.qf-result{display:none;text-align:center;}
.qf-result.is-active{display:block;}
.qf-result__title{font-family:var(--display);font-weight:700;color:var(--ink);
  font-size:clamp(26px,4vw,32px);line-height:1.1;margin-bottom:18px;}
.qf-accent{color:var(--accent);}
.qf-result__sub{font-family:var(--body);font-size:16px;line-height:1.5;color:var(--muted);
  max-width:46ch;margin:0 auto 24px;}
#qf-calendly-embed{width:100%;min-width:0;height:900px;overflow:hidden;}

@media (max-width:760px){
  .qf-card{padding:24px;}
  #qf-calendly-embed{height:820px;}
}
.ftr__social{display:flex;align-items:center;gap:10px;margin-top:19px;}
.ftr__social a{display:grid;place-items:center;width:32px;height:32px;color:#fff;
  transition:color .2s ease,transform .2s ease;}
.ftr__social a:hover{color:var(--accent);transform:translateY(-2px);}
.ftr__social svg{display:block;width:19px;height:19px;}

/* Dos halos suaves aportan profundidad a la sección larga de diferenciación. */
#por-que{
  background:
    radial-gradient(ellipse 650px 500px at 94% 9%,rgba(201,220,79,.16),transparent 72%),
    radial-gradient(ellipse 580px 520px at 4% 78%,rgba(201,220,79,.11),transparent 72%),
    var(--paper-2);
}

/* El verde recorre la página con menor intensidad en las secciones de lectura. */
#que-hacemos{
  background:
    radial-gradient(ellipse 620px 420px at 4% 5%,rgba(201,220,79,.11),transparent 72%),
    radial-gradient(ellipse 520px 430px at 94% 92%,rgba(201,220,79,.07),transparent 74%),
    var(--paper);
}
#como-trabajamos{
  background:
    radial-gradient(ellipse 650px 520px at 96% 24%,rgba(201,220,79,.07),transparent 75%),
    radial-gradient(ellipse 590px 560px at 4% 72%,rgba(201,220,79,.06),transparent 75%),
    var(--paper);
}
#preguntas-frecuentes{
  background:
    radial-gradient(ellipse 620px 500px at 94% 18%,rgba(201,220,79,.10),transparent 72%),
    radial-gradient(ellipse 520px 450px at 6% 87%,rgba(201,220,79,.07),transparent 74%),
    var(--paper-2);
}

/* ============================================================
   PÁGINAS DE DESTINO (gracias.html / confirmacion.html)
   ============================================================ */
body.page-end{display:flex;flex-direction:column;min-height:100vh;}
.end-main{flex:1;display:flex;align-items:center;padding-block:clamp(48px,8vw,96px);}
.end{width:100%;max-width:720px;margin-inline:auto;text-align:center;}
.end__check{
  display:grid;place-items:center;width:64px;height:64px;margin:0 auto 32px;
  border-radius:50%;background:var(--accent-soft);border:1px solid var(--accent-line);
  color:var(--accent);animation:endCheckIn .5s ease both;
}
.end__check svg{width:30px;height:30px;}
@keyframes endCheckIn{from{opacity:0;transform:scale(.8);}to{opacity:1;transform:scale(1);}}
.end__title{margin-bottom:22px;}
.end__sub{font-family:var(--body);font-size:19px;line-height:1.5;color:var(--ink-2);max-width:52ch;margin:0 auto 20px;}
.end__sub--accent{color:var(--accent);font-weight:600;font-size:20px;}
.end__body{font-family:var(--body);font-size:16px;line-height:1.6;color:var(--muted);max-width:58ch;margin-inline:auto;}

.end-cards{display:grid;grid-template-columns:1fr;gap:20px;margin-top:40px;text-align:left;}
.end-card{background:var(--paper-2);border:1px solid var(--line);border-radius:var(--r-lg);padding:28px;}
.end-card__icon{display:grid;place-items:center;width:40px;height:40px;margin-bottom:16px;
  border-radius:50%;background:var(--accent-soft);color:var(--accent);}
.end-card__icon svg{width:20px;height:20px;}
.end-card h3{font-family:var(--body);font-weight:700;font-size:17px;color:var(--ink);margin-bottom:8px;}
.end-card p{font-family:var(--body);font-size:14.5px;line-height:1.5;color:var(--muted);}
@media (min-width:640px){.end-cards{grid-template-columns:repeat(2,1fr);}}
